P.entries["item:stalker-claws"] = {n="Stalker Claws",s="Stalker Claws sunt ghearele recoltate de la pradatorii de preerie care strabat campiile domoale din Mulgore. Samanilor Tauren le sunt necesare pentru a ciopli totemurile traditionale de purificare, folosite la curatarea fantanilor cu apa contaminata.",h="Stalker Claws sunt ghearele recoltate de la pradatorii de preerie care strabat campiile domoale din Mulgore.",kw={"totem de purificare","Mulgore","Mull Thunderhorn","vanator de preerie","gheare de vanator","Thunderhorn Totem","fantana"},ang={["class:Shaman"]="Ghearele pradatorilor salbatici ai campiilor poarta in ele puritatea neimblanzita a naturii; sunt un material esential pentru legarea si intarirea totemurilor purificatoare.",["race:Tauren"]="Adunarea acestor gheare serveste datoriei sacre a tribului tau de a restaura apele sacre, otravite de intrusi industriali lipsiti de grija."},sec={{t="Pradatorii campiilor",b="Stepele inierbate din Mulgore adapostesc pradatori naturali letali, printre care si pandarii vicleni ai preriei. Aceste fiare supravietuiesc prin instinct pur si precizie ucigatoare, pastrand un echilibru esential in randuiala Earth Mother. Mull Thunderhorn, care cauta sa vindece pamantul pangarit, are nevoie de aceste gheare nu din rautate fata de animale, ci fiindca ferocitatea lor pura si naturala la vanatoare poarta rezonanta spirituala necesara pentru a contracara coruptia artificiala."},{t="Purificarea fantanilor",b="Cand intreprinderile goblinilor au inceput sa foreze si sa sape dupa minereuri in centrul Kalimdorului, otravurile chimice s-au infiltrat adanc in apele subterane care alimentau fantanile stramosesti ale taurenilor. In special, Thunderhorn Water Well a cazut prada unei contaminari abjecte. Legand Stalker Claws si Cougar Claws intr-un Thunderhorn Cleansing Totem, samanilor tribului le reusesc sa creeze un canal spiritual capabil sa curete noroiul si mizeria nefireasca din izvoarele naturale ale pamantului."}},faq={{q="De unde provin Stalker Claws?",a="Acestea sunt adunate vanand pradatori de preerie pe dealurile inierbate din Mulgore, in special la estul si vestul satului Bloodhoof Village.",al={"unde gasesc gheare de stalker","cine lasa gheare de stalker","sursa ghearelor de stalker"}},{q="De ce are Mull Thunderhorn nevoie de aceste gheare?",a="Mull Thunderhorn foloseste ghearele, impreuna cu cele de cougar de campie, pentru a confectiona un Thunderhorn Cleansing Totem. Puritatea si puterea innascute ale vanatorilor bastinasi ai campiilor sunt necesare pentru a purifica fantanile cu apa otravita.",al={"de ce se aduna ghearele de stalker","scopul lui Mull Thunderhorn","utilizarea ghearelor de stalker"}},{q="De ce este otravit Thunderhorn Water Well?",a="Fantana este afectata de poluarea industriala nenaturala cauzata de operatiunile goblinilor din Mulgore, care perturba echilibrul natural si otravesc panza freatica locala.",al={"cine a otravit fantana","de ce este bolnav izvorul Thunderhorn","poluarea Thunderhorn"}},{q="Ce se intampla dupa ce sunt adunate ghearele?",a="Dupa ce sunt adunate, Mull ciopleste ghearele intr-un totem purificator, care trebuie apoi dus direct la Thunderhorn Water Well pentru a curata coruptia persistenta.",al={"ce urmeaza","urmatorul pas dupa gheare","ritualul totemului de purificare"}}},fx={a496bd75={q="Ce sunt Stalker Claws?",a="Stalker Claws sunt ghearele naturale luate de la pradatorii de prerie, feline feroce care cutreiera campiile din Mulgore. Pentru un strain, sunt simple trofee de vanatoare, dar samanii tauren le vad drept intruchipari ale instinctului pradator natural al creaturii si ale armoniei sale cu pamantul.",al={"ce sunt ghearele de stalker","obiectul gheare de stalker","gheara de stalker"}}},fp="13,218,23.477.0,19.437.0,33.127.0,43.214.0,42.165.0,42.162.0"}
P.entries["item:steelgrill-s-tools"] = {n="Steelgrill's Tools"}
P.entries["item:steelsnap-s-rib"] = {n="Steelsnap's Rib",s="Steelsnap's Rib este un trofeu sumbru luat din carcasa hienei feroce Steelsnap, in Thousand Needles. Dus inapoi la Thunder Bluff, serveste drept dovada palpabila ca o creatura considerata lipsita de binecuvantarea Earthmother a fost ucisa.",h="Steelsnap's Rib este un trofeu sumbru luat din carcasa hienei feroce Steelsnap, in Thousand Needles.",kw={"camp e'thok","hunter rise","hiena","melor stonehoof","steelsnap","coasta lui steelsnap","thousand needles","thunder bluff"},ang={["class:Hunter"]="Prelevarea unei coaste de la un conducator alfa al haitei pune la incercare capacitatea unui hunter de a urmari o prada primejdioasa si de a elimina amenintarile care tulbura echilibrul salbaticiei.",["race:Tauren"]="Pentru tauren, aducerea acestui trofeu implineste o datorie fata de Earthmother, prin nimicirea unei creaturi a carei cruzime neinfranata pangareste echilibrul sacru."},sec={{t="O vanatoare dincolo de binecuvantare",b="Cele mai multe vanatori tauren sunt intreprinse pentru hrana, onoare sau pentru a cauta armonia cu natura. Steelsnap, insa, este o prada de cu totul alta natura. Cutreierand fundul canionului din Thousand Needles, la sud de Camp E'thok, aceasta hiena alfa feroce terorizeaza vietuitoarele pasnice si aduna haite de pradatori mai mici pentru varsari de sange fara rost. Cand maestrul de vanatoare Melor Stonehoof, de la Hunter Rise, il condamna pe Steelsnap la moarte, el cere un os gros - o coasta de-a lui Steelsnap - drept dovada de netagaduit ca tiranul a fost ucis si canionul curatat de napasta sa."}},faq={{q="La ce se foloseste Steelsnap's Rib?",a="Coasta este dusa la Melor Stonehoof, in varful Hunter Rise din Thunder Bluff, pentru a incheia vanatoarea lui Steelsnap. Ea dovedeste concret ca hiena feroce a fost invinsa.",al={"misiunea cu coasta lui Steelsnap","cine vrea coasta lui Steelsnap","ce fac cu coasta lui Steelsnap"}},{q="Unde il pot gasi pe Steelsnap pentru a obtine coasta?",a="Steelsnap cutreiera tinuturile de nord-vest din Thousand Needles, ratacind pe fundul canionului la sud de Camp E'thok, de obicei insotit de credincioasele sale animale de haita.",al={"locatia lui Steelsnap","unde se afla Steelsnap","gaseste-l pe Steelsnap"}},{q="De ce vrea Melor Stonehoof sa-l ucida pe Steelsnap?",a="Melor il considera pe Steelsnap un tiran nefiresc, aflat in afara binecuvantarii Earthmother. Spre deosebire de pradatorii obisnuiti, care vaneaza pentru a supravietui, Steelsnap raspandeste varsare de sange si teama fara rost printre fiarele pasnice, asa ca trebuie nimicit.",al={"de ce sa-l ucizi pe Steelsnap","motivul lui Melor Stonehoof","povestea lui Steelsnap"}},{q="Cine este Melor Stonehoof?",a="Melor Stonehoof este un vanator Tauren veteran, stationat la Hunter Rise din Thunder Bluff, care le incredinteaza celor dornici sa urmareasca prada misiuni de vanare a fiarelor periculoase din Kalimdor.",al={"cine este melor","locatia lui melor stonehoof","melor din hunter rise"}}},fx={["27efcb35"]={q="Ce este Steelsnap's Rib?",a="Este un os greu, luat din hoitul lui Steelsnap, o hiena de o ferocitate legendara, care terorizeaza canioanele din Thousand Needles. In loc sa fie un material de mestesugarit sau carne folositoare, osul dovedeste fara putinta de tagada ca bestia feroce a fost doborata.",al={"coasta lui steelsnap, ce este","ce este coasta lui steelsnap","osul lui steelsnap"}},["57ae26da"]={q="De unde provine Steelsnap's Rib?",a="Coasta provine chiar din ramasitele lui Steelsnap, o hiena neobisnuit de feroce care cutreiera campiile aride din Thousand Needles, la sud de Barrens. Pentru a o obtine, un vanator trebuie sa dea de urma fiarei si sa-i invinga atat pe Steelsnap, cat si haita sa.",al={"unde gasesti coasta lui Steelsnap","originea coastei lui Steelsnap","cine lasa coasta lui Steelsnap"}},["4a69fb67"]={q="De ce doreste Melor Stonehoof Steelsnap's Rib?",a="Melor Stonehoof cere coasta drept dovada materiala a mortii lui Steelsnap. Spre deosebire de vanatorile pentru hrana sau onoare, Melor ii trimite pe vanatori sa-l nimiceasca pe Steelsnap fiindca fiara se afla in afara binecuvantarii Earthmother, raspandind varsare de sange si teama printre fapturile mai pasnice. Intoarcerea cu osul dovedeste ca acel tinut a fost curatat de aceasta pata.",al={"de ce sa-i duci o coasta de la Steelsnap lui Melor","de ce are Melor nevoie de coasta","de ce sa aduni o coasta de la Steelsnap"}}},fp="15,245,27.553.0,33.177.0,42.148.0,47.240.0,23.165.0"}
