P.entries["item:teronis-journal"] = {n="Teronis' Journal",s="Teronis' Journal este un caiet de teren recuperat de langa ramasitele unui cercetas night elf din Ashenvale. Gasit alaturi de anchetatorul ucis, documenteaza cautarea unei nestemate misterioase si constituie o dovada esentiala pentru Sentinels din Astranaar.",h="Teronis' Journal este un caiet de teren recuperat de langa ramasitele unui cercetas night elf din Ashenvale.",kw={"Ashenvale","Astranaar","gema stralucitoare","Raene Wolfrunner","Raene's Cleansing","sentinele","Teronis","jurnalul lui Teronis"},ang={["faction:Alliance"]="Ducerea inapoi la Astranaar a insemnarilor de teren ale lui Teronis ajuta garnizoana sa coordoneze sprijinul si sa recupereze ramasitele cercetasului cazut.",["race:NightElf"]="Jurnalul reflecta indatoririle primejdioase ale cercetasilor night elf care se straduiesc sa protejeze padurile stravechi din Ashenvale de coruptia tot mai raspandita."},sec={{t="Ultimul raport al unui cercetas",b="Teronis, prieten de multa vreme al lui Raene Wolfrunner si aliat al Sentinels, s-a aventurat in tinuturile salbatice din Ashenvale in cautarea unei pietre pretioase pentru o nuia despre care credea ca putea domoli atacurile furbolgilor asupra poporului sau. Misiunea sa s-a incheiat brusc cand a cazut pe camp, inconjurat de creaturi agresive, in apropierea tarmului. Recuperat dintre lucrurile sale personale, acest jurnal a ramas intr-o stare remarcabil de buna, in ciuda mortii sale violente. El descrie descoperirile sale despre o piatra pretioasa radianta care facuse candva parte din acea nuia, oferindu-le aparatorilor din Astranaar indiciul esential pentru a duce la bun sfarsit misiunea neterminata."}},faq={{q="Cui ii apartinea acest jurnal?",a="Jurnalul ii apartinea lui Teronis, un prieten night elf al lui Raene Wolfrunner din Astranaar, care cauta in Ashenvale o cale de a incetini atacurile furbolgilor. A fost ucis in salbaticie inainte sa se poata intoarce cu descoperirile sale.",al={"cine a scris jurnalul","cine este Teronis","povestea lui Teronis"}},{q="Unde poate fi gasit jurnalul?",a="Jurnalul este recuperat scotocind prin lucrurile lui Teronis dupa ce trupul sau ucis este descoperit in tinuturile salbatice din Ashenvale, aproape de tarmurile populate de murlocii localnici.",al={"unde gasesc jurnalul","locatia jurnalului lui Teronis","cum obtin jurnalul"}},{q="Care este scopul ducerii jurnalului la Astranaar?",a="Inapoierea jurnalului catre Raene Wolfrunner o informeaza pe Astranaar despre moartea lui Teronis si le ofera Sentinels notitele necesare pentru a-i continua cautarea toiagului despre care spera ca va domoli atacurile furbolgilor.",al={"de ce sa duci jurnalul la Raene","cui trebuie sa-i dau jurnalul","predarea jurnalului"}},{q="Ce obiect cauta Teronis potrivit misiunii sale?",a="Teronis cauta o nestemata stralucitoare, una dintre piesele unei vergi faurite de vrajitorul mort Dartol. Cercetarile sale au indicat ca murlocii din apropiere ar fi putut scotoci artefactul.",al={"ce vana Teronis","ce nestemata cauta","nestemata lui Teronis"}}},fx={["5fb93f8f"]={q="Ce este Teronis' Journal?",a="Teronis' Journal este un jurnal personal pastrat de cercetasul night elf Teronis. Gasit printre lucrurile sale, langa trupul lui din Ashenvale, acesta descrie misiunea si primele cercetari legate de o nestemata misterioasa pe care fusese trimis sa o gaseasca, inainte sa-si gaseasca sfarsitul prematur.",al={"ce este jurnalul lui Teronis","obiectul jurnalul lui Teronis","despre jurnalul lui Teronis"}}},fp="16,244,22.597.0,31.225.0,27.172.0,57.204.0,59.184.0"}
P.entries["item:tharil-zun-s-head"] = {n="Tharil'zun's Head",s="Acest trofeu sinistru este capul taiat al lui Tharil'zun, conducatorul orcilor Blackrock Outrunners care ocupa Stonewatch. Marshal Marris il cere drept dovada de netagaduit ca a fost ucis comandantul care terorizeaza drumurile din Redridge.",h="Acest trofeu sinistru este capul taiat al lui Tharil'zun, conducatorul orcilor Blackrock Outrunners care...",kw={"alergatorii Blackrock","Lakeshire","Marshal Marris","Stonewatch","Stonewatch Keep","Tharil'zun","capul lui Tharil'zun"},ang={["faction:Alliance"]="Fiecare capetenie Blackrock ucisa reduce presiunea asupra orasului asediat Lakeshire, care lupta pentru supravietuire fara sprijin oficial din partea Stormwind."},sec={{t="Trofeul din Stonewatch",b="Orcii Blackrock incartiruiti in Stonewatch Keep au pus o presiune nemiloasa asupra Lakeshire, atacand fermele si pandind calatorii de-a lungul drumurilor. In fruntea acestor cete de jefuitori se aflau Blackrock Outrunners, aflati sub comanda lui Tharil'zun. Deoarece garnizoana din Lakeshire nu-si poate permite sa actioneze pe baza zvonurilor sau a unor victorii incomplete, Marshal Marris cere dovezi concrete ca liderul a fost ucis. A-i aduce capul taiat al lui Tharil'zun demonstreaza ca ambuscadele coordonate din fortareata au suferit o lovitura grea."}},faq={{q="Cine a fost Tharil'zun?",a="Tharil'zun era un comandant orc Blackrock viclean si crud, stationat la Stonewatch Keep. El ii conducea pe Blackrock Outrunners, care organizau ambuscade neincetate impreuna cu Renegades intre Lakeshire si fortareata.",al={"povestea lui Tharil'zun","cine este Tharilzun","conducatorul Tharil'zun"}},{q="De ce vrea Marshal Marris capul lui?",a="Intrucat Stormwind refuza sa trimita ajutor militar important in Redridge, Marshal Marris si garda din Lakeshire se bazeaza pe mercenari pentru a elimina amenintarile-cheie. Marris cere dovada de netagaduit a mortii lui Tharil'zun pentru a se asigura ca liderii Outrunners au fost cu adevarat infranti.",al={"de ce capul lui tharil'zun","dovada cu capul lui marris","recompensa lui marris"}},{q="Unde poate fi gasit Tharil'zun?",a="Tharil'zun stapaneste Stonewatch Keep, in dealurile estice din Redridge Mountains, inconjurat de orci Blackrock si gnolli.",al={"locatia lui tharil'zun","unde este tharil'zun","gaseste-l pe tharil'zun"}},{q="Oare luarea capului lui Tharil'zun pune capat amenintarii Blackrock?",a="Nu. Desi uciderea lui Tharil'zun perturba ambuscadele celor din Outrunners, Blackrock clan mentine o forta masiva, bine inradacinata, in Stonewatch Keep si de-a lungul Redridge Mountains.",al={"au disparut orcii","am salvat redridge","dupa tharil'zun"}}},fx={a015b31b={q="Ce este Tharil'zun's Head?",a="Acest cap taiat este dovada fizica ca Tharil'zun, comandantul care coordoneaza ambuscadele orcilor Blackrock din jurul Stonewatch Keep, a fost ucis. Adus inapoi in Lakeshire, le arata garzilor asediate ale orasului ca unul dintre cei mai periculosi conducatori de campanie din Blackrock clan, in Redridge Mountains, nu va mai teroriza drumurile.",al={"obiectul cap Tharil'zun","povestea capului lui Tharil'zun"}},f673cecf={q="De unde provine Tharil'zun's Head?",a="Este luat direct de pe cadavrul lui Tharil'zun, un conducator de seama al orcilor Blackrock care isi avea baza in ruinele Stonewatch Keep. Dupa ce este infrant in lupta de tine sau de aparatorii din Lakeshire, capul ii este revendicat drept trofeu incontestabil si dovada sumbra a mortii sale.",al={"cine a luat capul lui Tharil'zun","originea capului lui Tharil'zun","de unde provine capul lui Tharil'zun"}}},fp="17,233,20.525.0,19.201.0,38.254.0,26.117.0,55.177.0"}
P.entries["item:tharnariun-s-hope"] = {n="Tharnariun's Hope"}
P.entries["item:the-book-of-ur"] = {n="The Book of Ur",s="Book of Ur este un tratat magic erudit, scris de vrajitorul Ur din Dalaran, trecut in nefiinta, care detaliaza cercetarile sale despre entitati extradimensionale neobisnuite. Lasata in urma in Shadowfang Keep, cartea a ajuns in mainile lui Archmage Arugal, inainte de a starni interesul aprins al cercetatorilor Forsaken din Undercity.",h="Book of Ur este un tratat magic erudit, scris de vrajitorul Ur din Dalaran, trecut in nefiinta, care...",kw={"Apothecarium","Arugal","Book of Ur","Dalaran","Keeper Bel'dugur","Shadowfang Keep","Silverpine","Ur"},ang={["class:Mage"]="Scrierile lui Ur amintesc fara menajamente de aria de cercetare a savantilor din Dalaran, extinsa si asupra altor taramuri, si de consecintele letale ale folosirii gresite a acelor cunostinte interzise de catre magi ambitiosi precum Arugal.",["race:Undead"]="Asigurarea lucrarii lui Ur ii ajuta direct pe invatatii Dark Lady din Apothecarium, transformand cercetarea prudenta a unui vrajitor uman cazut intr-o putere concreta pentru Forsaken."},sec={{t="Magul din Dalaran",b="Inainte ca Dalaran sa cada in mainile Scourge, Ur era renumit printre Kirin Tor pentru cercetarile sale ezoterice asupra altor planuri ale existentei si creaturilor de dincolo de lumea noastra. In ciuda fascinatiei sale pentru magia extraplanara, Ur era calauzit de prudenta si retinere etica, alegand sa-si consemneze descoperirile in loc sa rupa nechibzuit valul dintre lumi. In mod tragic, cand Scourge a atacat orasul violet, priceperea sa magica si scrupulele morale nu au fost de ajuns pentru a-l salva."},{t="Ambitia Forsaken",b="Dupa moartea lui Ur, scrierile sale au ajuns in posesia lui Archmage Arugal, care a folosit cercetarile pentru a chema monstruosii worgen in Silverpine Forest. Tomul se afla acum pe rafturile din Shadowfang Keep. Vestea despre existenta sa a atras atentia lui Keeper Bel'dugur din Apothecarium, in Undercity. Spre deosebire de autorul sau initial, Forsaken nu au nicio retinere in a folosi magia periculoasa si neingradita pentru a-si asigura supravietuirea si cuceririle."}},faq={{q="Cine a fost Ur?",a="Ur a fost un mag uman de seama din Dalaran, inainte de Third War. A cercetat pe larg alte dimensiuni si creaturi extraplanare, desi a refuzat sa le invoce din cauza pericolului imens pe care il reprezentau.",al={"cine a scris Book of Ur","magul din Dalaran Ur"}},{q="Unde se afla Book of Ur?",a="Cartea se afla pe un raft din Shadowfang Keep, in Silverpine Forest, mai exact in incaperea in care salasluieste masiva fiara Fenrus.",al={"locatia Book of Ur","unde se afla Book of Ur"}},{q="De ce vrea Keeper Bel'dugur cartea?",a="Keeper Bel'dugur strange scrierile lui Ur in numele celor interesati din Undercity. Forsaken cred ca scrupulele morale ale lui Ur l-au impiedicat sa-si atinga adevarata putere si vor sa-i foloseasca cercetarile extraplanare fara constrangeri etice, pentru a-si spori propria forta.",al={"Keeper Bel'dugur Book of Ur","de ce vrea Undercity cartea"}},{q="Cum a ajuns cartea in Shadowfang Keep?",a="Dupa ce Ur a murit in timpul caderii Dalaranului, Archmage Arugal i-a preluat cercetarile. Impins la masuri disperate pentru a se apara de Scourge, Arugal a dus notitele in Silverpine Forest si a folosit teoriile lui Ur despre invocare pentru a atrage worgenii in Azeroth.",al={"Arugal si Book of Ur","cum a obtinut Arugal cartea"}}},fx={["62a01830"]={q="Ce este Book of Ur?",a="Book of Ur este un tom erudit care cuprinde cercetarile ezoterice ale lui Ur, un mag desavarsit din Dalaran. Acesta detaliaza studiile sale ample despre alte lumi si fenomene arcane periculoase - cunostinte atat de puternice, incat Archmage Arugal a folosit mai tarziu scrierile lui Ur pentru a chema worgenii monstruosi in Silverpine Forest.",al={"ce este Book of Ur","istoria lui Book of Ur","ce este cartea lui Ur"}},["905bb2c4"]={q="De unde provine Book of Ur si cine l-a facut?",a="Cartea a fost scrisa in regatul magic Dalaran de catre magul Ur, inainte ca Scourge sa distruga orasul. Ur si-a consemnat teoriile arcane si cercetarile asupra altor dimensiuni, insa lucrarea a fost abandonata dupa ce a murit in timpul caderii Dalaranului.",al={"cine a scris Book of Ur","originea Book of Ur","de unde provine Book of Ur"}}},fp="14,296,19.475.0,17.463.1,11.205.0,32.142.0,40.276.0,43.252.0"}
P.entries["item:the-collector-s-schedule"] = {n="The Collector's Schedule",s="Langa Brackwell Pumpkin Patch, The Collector's Schedule indica momentul in care transporturile ilegale de aur traverseaza Elwynn Forest. Gnolls poarta itinerarul scris de mana, iar Marshal Dughan recunoaste numele consemnat in el.",h="Langa Brackwell Pumpkin Patch, The Collector's Schedule indica momentul in care transporturile ilegale de aur...",kw={"brackwell","colectionar","dughan","elwynn","aur","goldshire","mine","program"},ang={["faction:Alliance"]="Ca membru al Alliance, poti vedea cat de putin control are Stormwind asupra propriului teritoriu, cand echipaje neautorizate ii acapareaza resursele din apropierea capitalei.",["profession:Mining"]="Ca miner, poti vedea ca minele din Elwynn nu sunt parasite: filoane bogate de aur sunt exploatate si transportate."},sec={{t="Aur furat si transporturi secrete",b="Collector's Schedule consemneaza datele si orele transporturilor de aur din minele din Elwynn. Stormwind nu a mai exploatat oficial minele de luni intregi, alungat de banditism si de incursiunile creaturilor, si totusi minereul continua sa plece in mod regulat. Itinerarul precizeaza zilele si orele la care o persoana numita The Collector primeste fiecare transport. Urmele duc la o tabara de langa Brackwell Pumpkin Patch, in estul Elwynn Forest. Cand Marshal Dughan vede programul, recunoaste numele Collector. Nu se stie cine plateste pentru aurul furat."}},faq={{q="Ce este Collector's Schedule?",a="Collector's Schedule consemneaza cand pleaca transporturile de aur din minele abandonate din Elwynn Forest, cu destinatia un agent numit The Collector.",al={"ce este biletul acesta","programul colectionarilor","programul de aur"}},{q="De unde provine programul?",a="Gnoll-ii poarta programul de-a lungul malurilor si dealurilor din Elwynn Forest. Poate l-au luat de la un curier sau poate sunt implicati in transportul aurului.",al={"cine lasa programul","unde gasesti programul"}},{q="Cine este Collector?",a="Collector este un agent stationat langa Brackwell Pumpkin Patch, in estul Elwynn Forest. Marshal Dughan recunoaste numele, dar nu stie cui ii slujeste agentul.",al={"cine este collector","identitatea colectionarului"}},{q="De ce il ingrijoreaza acest program pe Marshal Dughan?",a="Marshal Dughan este alarmat, deoarece Stormwind nu a avut mineri oficiali in minele din Elwynn de luni intregi, si totusi de acolo continua sa plece transporturi considerabile de aur. Asta indica o operatiune miniera organizata si ilegala in interiorul regatului.",al={"de ce-i pasa lui Dughan","aurul din minele Elwynn"}}},fp="24,211,32.538.0,33.129.0,33.150.0,21.170.0,47.223.0"}
P.entries["item:the-embalmer-s-heart"] = {n="The Embalmer's Heart",s="Embalmer's Heart este o relicva profana care bate in trupul strigoi al Elizei, ingropata adanc in Duskwood. Candva ii apartinuse unui alchimist indurerat, cunoscut drept Imbalsamatorul; prin magie neagra, inima a fost transplantata pentru a-i readuce la viata sotia decedata si a devenit ancora principala a puterii sale pervertite.",h="Embalmer's Heart este o relicva profana care bate in trupul strigoi al Elizei, ingropata adanc in Duskwood.",kw={"mireasa imbalsamatorului","darkshire","duskwood","eliza","ello ebonlocke","inima imbalsamatorului","imbalsamatorul"},ang={["class:Warlock"]="Transplantarea unui organ legat de suflet, inca palpitand, pentru a sustine o neviata necromantica este o realizare ambitioasa, desi haotica, in modelarea carnii si manipularea sufletului.",["race:Human"]="Caderea tragica a alchimistului binevoitor este o pilda sumbra, rostita in soapta de oamenii napastuiti din Duskwood."},sec={{t="O iubire care a infruntat moartea",b="Potrivit folclorului din Darkshire, Imbalsamatorul a fost candva un alchimist bland, a carui minte s-a sfaramat la moartea iubitei sale sotii, Eliza. Disperat sa o smulga mormantului, a recurs la vrajitorii spurcate si si-a scos propria inima, punand-o in pieptul lipsit de viata al Elizei. Desi transfuzia profana i-a readus cu succes cadavrul la viata, invierea a transformat-o intr-o creatura lacoma, mistuita de o foame nesatioasa de carne umana vie, silindu-l pe alchimistul ingrozit sa o ingroape din nou in pamant."},{t="Un scut pentru Darkshire",b="Desi a fost smulsa din piept, inima ramane sursa puterii intunecate nepieritoare a Embalmer-ului si continua sa bata in mormantul Elizei. Primarul Ello Ebonlocke isi da seama ca singura cale de a-l lipsi pe Embalmer de vrajitoria sa este sa zdrobeasca mireasa reanimata si sa-i ia organul pulsand. Asigurandu-si inima cat inca bate, conducerea din Darkshire spera sa intoarca propria magie malefica a necromantului impotriva lui, folosindu-i esenta drept scut impotriva ororilor sale."}},faq={{q="De ce are Eliza inima Embalmer-ului?",a="Indurerat de moartea sotiei sale, Eliza, Embalmer a folosit magie interzisa pentru a-si pune propria inima inca batand in cadavrul ei, ca s-o invie. Ritualul a readus-o la viata, dar a blestemat-o cu o foame nesatioasa de carne omeneasca.",al={"de ce are Eliza inima","inima imbalsamatorului din Eliza","cine a pus inima in Eliza"}},{q="De ce vrea Mayor Ebonlocke ca inima sa fie adusa inapoi la Darkshire?",a="Primarul Ello Ebonlocke intentioneaza sa foloseasca magia intunecata care inca reverbereaza in inima ce bate, creand o pavaza defensiva deasupra Darkshire, neutralizand puterea Imbalsamatorului si transformand-o intr-o protectie pentru oras.",al={"de ce vrea Ello inima","planul lui Ebonlocke cu inima","ce face Darkshire cu inima"}},{q="Cum supravietuieste Imbalsamatorul fara inima?",a="Prin vrajitoriile intunecate pe care le practica, Imbalsamatorul si-a legat direct forta vitala si puterea de inima transplantata, putand astfel sa dainuie chiar si atunci cand organul bate in ramasitele ingropate ale sotiei sale.",al={"este imbalsamatorul in viata","cum poate fi in viata imbalsamatorul fara inima"}},{q="Unde se poate gasi inima?",a="Inima se afla in Eliza, care ramane ingropata intr-un mormant ascuns din Duskwood. Poate fi luata doar infruntand si invingand mireasa lacoma, readusa la viata.",al={"unde este inima imbalsamatorului","locatia mormantului Elizei","cum obtii inima imbalsamatorului"}}},fx={cac9cdef={q="Ce este Embalmer's Heart?",a="Este inima batand, la propriu si sustinuta prin magie, a alchimistului renegat cunoscut drept Embalmer. Innebunit de durerea pierderii sotiei sale, Eliza, si-a scos propria inima si a asezat-o in trupul ei pentru a o readuce la viata. Chiar si despartita de pieptul sau, inima slujeste drept vas si canal al puterii sale necromantice, mentinand atat starea de strigoi blestemat a Elizei, cat si propria sa vitalitate necurata.",al={"ce este inima imbalsamatorului","povestea inimii imbalsamatorului","inima imbalsamatorului"}}},fp="20,293,24.551.0,22.491.1,41.225.0,66.220.0,48.204.0,29.172.0"}
P.entries["item:the-general-s-response"] = {n="The General's Response",s="General Marcus Jonathan trimite vesti la Lakeshire, in timp ce Redridge asteapta ajutor. Mesajul sau ia act de rugamintea lui Magistrate Solomon de a primi sprijin impotriva orcilor Blackrock si a gnoll, dar nu promite intariri imediate din Stormwind.",h="General Marcus Jonathan trimite vesti la Lakeshire, in timp ce Redridge asteapta ajutor.",kw={"general marcus jonathan","lakeshire","magistrate solomon","messenger to stormwind","redridge","stormwind","raspunsul generalului"},ang={["faction:Alliance"]="Reactia lui Stormwind arata presiunea la care este supusa Grand Alliance. Lakeshire sangereaza, in timp ce curtea pare in mod straniu indiferenta fata de situatia sa.",["race:Human"]="Pentru Human din regatele sudice, raspunsul intarziat arata ruptura tot mai mare dintre oamenii care lupta pentru supravietuire in provincii si nobilimea izolata din Stormwind Keep."},sec={{t="Un impas diplomatic",b="Magistrate Solomon trimite un apel urgent catre Stormwind City, cerand trupe care sa apere Redridge de clanurile Blackrock orc si cetele de razboi ale gnolls, care se aduna. General Marcus Jonathan raspunde ca apelul a fost inaintat tronului, dar ca nu vor fi trimisi soldati deocamdata. El ordona ca scrisoarea sa fie trimisa inapoi la Lakeshire. Solomon ramane tulburat de intarzierea din Stormwind si banuieste ca este ceva in neregula cu conducatorii sai."}},faq={{q="Ce este scris in The General's Response?",a="General Marcus Jonathan ii jeleste pe cei morti si spune ca il va informa pe King despre necazurile din Lakeshire. Spera sa aduca intariri si marturiseste ca Majestatea Sa a fost greu de gasit si s-a purtat ciudat.",al={"continutul scrisorii","ce spune scrisoarea","scrisoarea generalului"}},{q="De ce nu poate General Marcus Jonathan sa trimita trupe la Lakeshire?",a="General Jonathan asteapta raspunsul Regelui inainte de a promite intariri. In mod confidential, ii spune lui Solomon ca Majestatea Sa a fost greu de gasit si s-a purtat ciudat.",al={"de ce nu vin intariri","de ce nu ajuta Stormwind Lakeshire","de ce nu vine nimeni in ajutor"}},{q="Cum reactioneaza Magistrate Solomon la scrisoare?",a="Magistrate Solomon este profund tulburat de mesaj. Intarzierea celor din Stormwind nu are niciun sens pentru el, cand Lakeshire se confrunta cu un asemenea pericol, si se teme ca nepasarea ascunde probleme si mai grave in regat.",al={"reactia lui Solomon","ce crede Solomon","raspunsul lui Solomon"}}},fx={["3ebc4cbb"]={q="Ce este General's Response?",a="Este o scrisoare oficiala, sigilata, redactata de General Marcus Jonathan, comandantul Stormwind City Guard, si adresata lui Magistrate Solomon din Redridge. Transportata de curieri intre capitala si Lakeshire, scrisoarea transmite raspunsul oficial al inaltului comandament la cererea disperata a celor din Redridge pentru intariri regale.",al={"care este raspunsul generalului","obiectul raspunsul generalului","ce este scrisoarea asta"}},["174955dc"]={q="De unde provine The General's Response si cine l-a facut?",a="Scrisoarea este redactata chiar de General Marcus Jonathan, in Stormwind City. Dupa ce primeste petitia urgenta a lui Magistrate Solomon in Valley of Heroes, Jonathan scrie acest raspuns oficial in asteptarea vestilor de la curtea regala si te insarcineaza sa i-l duci inapoi magistratului din Lakeshire.",al={"cine a scris raspunsul generalului","de unde provine raspunsul generalului","cine a trimis raspunsul generalului"}},d0ef00e9={q="De ce si-ar dori cineva The General's Response?",a="Magistrate Solomon asteapta cu nerabdare acest mesaj, ca sa afle daca Stormwind va trimite soldati sa salveze Lakeshire de orcii si gnolii Blackrock. Livrarea lui le va spune limpede conducatorilor orasului napastuit ce ajutor poate - sau nu poate - oferi regatul.",al={"de ce vrea solomon scrisoarea","cine vrea raspunsul generalului","de ce trebuie dus raspunsul generalului"}}},fp="22,223,21.409.0,42.196.0,59.159.0,48.198.0"}
P.entries["item:the-lich-s-spellbook"] = {n="The Lich's Spellbook",s="Lich's Spellbook este un volum de cunostinte necromantice pastrat intr-un cufar de pe insula din Brightwater Lake. Recuperat pentru Bethor Iceshard in Undercity, tomul dezvaluie adevarata identitate si imensa putere magica a unui lich strigoi retras, care salasluieste chiar la nord de capitala Forsaken.",h="Lich's Spellbook este un volum de cunostinte necromantice pastrat intr-un cufar de pe insula din Brightwater...",kw={"bethor iceshard","brightwater lake","gunther arcanus","lich","necromantie","carte de vraji","tirisfal glades","undercity"},ang={["class:Mage"]="Cartea de vraji reprezinta o punte extraordinara intre vrajitoria clasica din Dalaran si necromantia intunecata, aratand cum si-au extins considerabil arta vrajitorii muritori dupa ce au cazut prada strigoirii.",["race:Undead"]="Tomele dovedesc ca nu toti cei care s-au eliberat de sub stapanirea Lich King s-au alaturat imediat celor din Forsaken, subliniind neincrederea persistenta dintre supravietuitorii strigoi razleti din Tirisfal."},sec={{t="Tomele unui maestru retras",b="Pe o insula izolata din Brightwater Lake se inalta un lich enigmatic, inconjurat de gardieni scheletici. Desi isi pastreaza vointa proprie, acest vrajitor nu are incredere in lumea de dincolo de insula, confundandu-i pe toti ceilalti morti-vii cu sclavi ai Scourge si poruncindu-le slujitorilor sai sa-i distruga pe toti cei care se apropie. Bethor Iceshard, aflat in cautarea unor necromanti inzestrati care sa intareasca randurile Forsaken de sub regina Sylvanas Windrunner, a insarcinat un emisar sa se infiltreze in tabara de pe insula si sa recupereze cartea de vraji a lichului. Studiind-o, Bethor spera sa-i desluseasca maiestria magica stapanului si sa descopere cine fusese inainte ca moartea sa puna stapanire pe Lordaeron."},{t="Demascarea lui Gunther Arcanus",b="Cand a deschis paginile stralucitoare ale cartii de vraji recuperate, Bethor Iceshard a facut o descoperire uluitoare: pustnicul era vechiul sau prieten si camarad de arme de dinainte de Third War, Gunther Arcanus. Inca din viata, Gunther fusese un necromant prodigios, iar scrierile sale dezvaluiau ca artele lui devenisera si mai puternice dupa moarte. Bethor si-a dat seama ca obtinerea loialitatii lui Gunther le-ar oferi Forsaken un maestru de nepretuit al artelor intunecate, cu conditia ca cineva sa-l poata convinge pe lichul suspicios ca Forsaken sunt cu adevarat liberi de sub stapanirea Lich King-ului."}},faq={{q="Unde se gaseste Lich's Spellbook?",a="Cartea de vraji se afla intr-un recipient numit Cartile lui Gunther, in tabara de pe insula centrala din Brightwater Lake, in nordul Tirisfal Glades.",al={"unde este cartea","locatia cartii de vraji","cartile lui Gunther"}},{q="Cui ii apartine aceasta carte de vraji?",a="Ii apartine lichului retras si independent de pe insula din Brightwater Lake. Bethor Iceshard spera ca studiul paginilor sa-i dezvaluie identitatea si talentele proprietarului.",al={"a cui este cartea","identitatea licheului","cine a scris cartea de vraji"}},{q="De ce vrea Bethor Iceshard cartea?",a="Bethor Iceshard a cautat cartea pentru a deduce identitatea misteriosului lich si a-i evalua maiestria in necromantie, sperand sa-l atraga pe retras in slujba Lady Sylvanas si a Forsaken.",al={"de ce sa iau cartea","motivul misiunii lui Bethor","de ce vrea Undercity acest lucru"}},{q="De ce ii ataca lichul pe cei care ii viziteaza insula?",a="Lichul crede ca toti ceilalti strigoi din regiune sunt in continuare sclavi controlati mental de Scourge. Paralizat de suspiciune, le porunceste slugilor sale sa atace pe oricine se apropie de sanctuarul sau.",al={"de ce este Gunther ostil","de ce ataca slugile","Brightwater Lake ostil"}},{q="Ce spera Bethor sa afle despre autor?",a="Bethor spera sa afle cine a fost in viata lichul izolat si daca stiinta sa necromantica le-ar putea fi de folos celor din Forsaken.",al={"ce va invata Bethor","studiul autorului lich","studiul cartii de vraji a lui Bethor"}}},fx={["44ee6981"]={q="De unde provine The Lich's Spellbook si cine a facut-o?",a="Cartea de vraji ii apartine lichului retras, cu vointa proprie, care locuieste pe insula din Brightwater Lake. El a scris si a ingrijit singur tomul, umplandu-i paginile stralucitoare cu artele sale de necromantie, atat in timpul vietii, cat si dupa transformarea in lich. Bethor Iceshard vrea cartea pentru a afla cine a fost lichul.",al={"cine a facut cartea de vraji a lichului","originea cartii de vraji a lichului","de unde provine cartea de vraji a lichului"}}},fp="20,288,26.593.0,25.555.1,36.159.0,24.167.1,39.194.0,48.187.0,48.121.1"}
P.entries["item:the-state-of-lakeshire"] = {n="The State of Lakeshire",s="State of Lakeshire este un raport scris urgent de Magistrate Solomon, care descrie criza militara disperata ce cuprinde orasul Lakeshire. Adresat direct lui General Marcus Jonathan din Stormwind, documentul implora capitala sa trimita intariri ale armatei regale inainte ca asezarea din Redridge sa cada.",h="State of Lakeshire este un raport scris urgent de Magistrate Solomon, care descrie criza militara disperata...",kw={"depesa","magistrate solomon","marcus jonathan","redridge","intariri","raport","starea din lakeshire","stormwind"},ang={["faction:Alliance"]="Raportul arata cat de vulnerabile sunt asezarile de la margine si scoate in evidenta inertia politica ce blocheaza in prezent ajutorul militar din capitala.",["race:Human"]="Pentru oamenii regatului, transportarea acestui document subliniaza ruptura tot mai adanca dintre oamenii de rand din Redridge si coroana indepartata din Stormwind."},sec={{t="Un strigat de ajutor",b="Scrisa de Magistrate Solomon in toiul atacurilor neincetate asupra tinutului Redridge, 'The State of Lakeshire' descrie situatia disperata care ameninta asezarea. Asediata de orci Blackrock si hienoizi ostili, Lakeshire nu are destui oameni in zona pentru a-si apara hotarele la nesfarsit. Incredintata unor curieri de incredere care calatoresc spre vest, in Elwynn Forest, aceasta depesa poarta cererea oficiala a lui Solomon ca Stormwind Army sa intervina si sa apere tinuturile rasaritene ale regatului."},{t="Birocratie si impas",b="La primirea raportului la portile din Stormwind, General Marcus Jonathan recunoaste rangul nobil al lui Solomon si gravitatea vestii. Totusi, Jonathan nu poate mobiliza armata de unul singur. Desfasurarile militare necesita consimtamantul explicit al coroanei, astfel ca apelul urgent din Lakeshire trebuie sa astepte o intrunire la nivel inalt cu tanarul rege si regentul Bolvar Fordragon."}},faq={{q="Ce este State of Lakeshire?",a="Este un raport oficial scris de Magistrate Solomon, care descrie pericolul militar cu care se confrunta Lakeshire si implora Stormwind sa trimita intariri.",al={"document despre situatia din Lakeshire","ce este acest raport","mesajul lui Solomon"}},{q="Cine ar trebui sa primeasca acest mesaj?",a="Raportul ii este adresat direct generalului Marcus Jonathan, comandantul garzii orasului Stormwind si al fortelor regale, aflat la portile orasului.",al={"cine primeste raportul","cui trebuie sa-l predai","raportul lui Marcus Jonathan"}},{q="De ce are Lakeshire nevoie de intariri regale?",a="Asezarea este asediata fara incetare de orci Blackrock, gnolli Shadowhide si murloci locali, impingand garda orasului la limita puterilor.",al={"de ce este Lakeshire in pericol","ce ameninta Redridge"}},{q="Trimite General Marcus Jonathan ajutor imediat?",a="Nu. Desi generalul recunoaste gravitatea crizei, nu poate desfasura armata fara aprobarea oficiala a regelui, asa ca solicitarea trebuie mai intai analizata de coroana.",al={"ajuta Stormwind","trimite Jonathan trupe"}}},fx={["629511cc"]={q="De unde provine The State of Lakeshire si cine l-a facut?",a="Magistrate Solomon, conducatorul civil si judecatorul din Lakeshire, a redactat acest raport esential. Confruntat cu presiuni neintrerupte din partea fortelor ostile care inconjoara orasul, Solomon a scris personal mesajul pentru a descrie oficial situatia primejdioasa din Redridge si a cere ajutor militar imediat de la inaltul comandament al Stormwindului.",al={"cine a scris state of Lakeshire","cine a creat state of Lakeshire","autorul state of Lakeshire"}},["09d61feb"]={q="De ce este atat de urgent nevoie de The State of Lakeshire?",a="Lakeshire este asediat fara incetare, iar Magistrate Solomon stie ca orasul nu poate rezista singur fara intariri regale. General Marcus Jonathan are nevoie de aceasta dare de seama oficiala pentru a justifica trimiterea unor unitati din Stormwind Army si a prezenta regelui si lui Highlord Bolvar Fordragon situatia disperata din Lakeshire.",al={"de ce este nevoie de actul din Lakeshire","de ce sa predau actul din Lakeshire","de ce vrea Marcus Jonathan actul din Lakeshire"}}},fp="22,321,13.466.0,24.381.0,31.159.0,41.153.0,45.142.0,51.179.0"}
