P.entries["item:warsong-saw-blades"] = {n="Warsong Saw Blades",s="Warsong Saw Blades sunt unelte industriale de taiere specializate, comandate pentru operatiunile de defrisare ale Horde in Ashenvale. Livrate prin retelele logistice ale goblinilor, sunt vitale pentru buna functionare a utilajelor forestiere din Warsong Lumber Camp.",h="Warsong Saw Blades sunt unelte industriale de taiere specializate, comandate pentru operatiunile de defrisare...",kw={"taierea lemnului in Ashenvale","Locke Okarr","Pixel","Splintertree Post","tabara de taietori de lemne Warsong","panze de ferastrau Warsong"},ang={["faction:Horde"]="Intreaga expansiune a Horde in centrul Kalimdor depinde de lemnul din Ashenvale, ceea ce face din pastrarea si intretinerea utilajelor de taiat lemne Warsong o prioritate strategica esentiala.",["race:NightElf"]="Fiecare lada de lame de ferastrau faurite de goblini reprezinta profanarea continua a stravechiului coronament din Ashenvale si uciderea spiritelor sacre ale padurii."},sec={{t="Silvicultura industriala",b="Eforturile de exploatare forestiera ale clanului Warsong din Ashenvale se bazeaza in mare masura pe utilaje grele, furnizate si intretinute prin ingineria goblin. Topoarele obisnuite nu pot satisface singure cererea uriasa a Horde de lemn din Kalimdor, asa ca sunt necesare motoare cu aburi si fierastraie circulare care taie necontenit prin lemnul brut. Cum lemnul de esenta tare stravechi din Ashenvale toceste si rupe rapid lamele obisnuite, livrarile constante de lame de schimb sunt vitale pentru functionarea fabricilor de cherestea de la Warsong Lumber Camp."},{t="Asigurarea transportului",b="Aprovizionarea cu piese mecanice din adancul unui teritoriu disputat este o problema logistica permanenta. In timp ce alte provizii pentru exploatarea lemnului sunt adesea interceptate de furbolgi ostili sau de satyri, transporturile de panze pentru ferastraie sunt gestionate prin contacte goblin precum Pixel, la Splintertree Post. Strangerea acestor panze, alaturi de franghie, ulei si topoare, ii ingaduie maestrului lemnar Locke Okarr sa mentina tabara in functiune, in ciuda sabotajelor neintrerupte ale aparatorilor bastinasi."}},faq={{q="La ce se folosesc Warsong Saw Blades?",a="Sunt piese de schimb pentru fierastraiele circulare, destinate tocatoarelor grele si morilor mecanice de lemn care functioneaza la Warsong Lumber Camp, in sud-estul Ashenvale.",al={"scopul panzei de fierastrau","la ce folosesc panzele de fierastrau","la ce servesc"}},{q="Cine furnizeaza aceste panze de ferastrau Horde-ului?",a="Lamele sunt manevrate de negustori si responsabili cu logistica goblini. Pixel, un goblin stationat la Splintertree Post, supravegheaza sosirea acestui transport mecanic pentru iscoadele Warsong.",al={"cine a facut lamele de fierastrau","de unde provin lamele","furnizorul lamelor de fierastrau"}},{q="De ce are nevoie Horde de atatea panze de ferastrau?",a="Copacii batrani si deasa din Ashenvale tocesc repede taisurile, iar Horde are nevoie de cantitati uriase de lemn pentru a construi asezari pe campiile aride din Durotar si Barrens. Taierile neintrerupte uzeaza utilajele mai repede decat le pot repara fierarii locali.",al={"de ce sunt atatea lame","cererea Warsong pentru taierea lemnelor","de ce sunt necesare fierastraiele"}},{q="Cine strange proviziile pentru taierea lemnelor?",a="Locke Okarr, un orc care supravegheaza transporturile de provizii de la Splintertree Post, organizeaza recuperarea panzei de ferastrau, alaturi de ulei, franghii si topoare, pentru a le livra taberei forestiere.",al={"cine vrea panzele de ferastrau","cine ia panzele de ferastrau","misiunea lui Locke Okarr"}}},fx={["12f75673"]={q="Ce sunt Warsong Saw Blades?",a="Aceste lame metalice de mare rezistenta sunt componente mecanice esentiale, construite pentru utilajele industriale de taiat lemne ale celor din Warsong Outrider. Orcs se bazeaza foarte mult pe exploatarea forestiera mecanizata pentru a recolta lemnul stravechi si dens din Ashenvale, insa copacii grosi tocesc rapid dintii taietori. Fara o rezerva constanta de panze de ferastrau ascutite si durabile, operatiunile forestiere Warsong se opresc.",al={"ce sunt panzele de ferastrau Warsong","obiectul panze de ferastrau Warsong","ce sunt aceste panze de ferastrau"}}},fp="18,253,19.486.0,21.436.0,41.166.0,43.184.0,43.272.0,39.174.0"}
